language plpgsql
set search_path = ''
as $$
begin
  if new.time_zone is null or not exists (
    select 1 from pg_catalog.pg_timezone_names as zone where zone.name = new.time_zone
  ) then
    raise exception using errcode = '22023', message = 'INVALID_SALON_TIME_ZONE';
