create function public.list_admin_bookings(
  p_view text,
  p_offset integer default 0,
  p_limit integer default 51
)
returns table (
  id uuid,
  customer_name text,
  phone text,
  service_id uuid,
  service_name text,
  slot_time timestamptz,
  end_time timestamptz,
  status public.booking_status
)
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_time_zone text;
  v_today date;
  v_today_start timestamp;
  v_tomorrow_start timestamp;
begin
  -- Gate before validating input or inspecting any booking/customer data.
  if not public.is_admin() then
    raise exception using errcode = '42501', message = 'ADMIN_REQUIRED';
  end if;
  if p_view is null or p_view not in ('today', 'upcoming')
     or p_offset is null or p_offset not between 0 and 10000
     or p_limit is null or p_limit not between 1 and 51 then
    raise exception using errcode = '22023', message = 'INVALID_ADMIN_BOOKING_INPUT';
  end if;

  select settings.time_zone into strict v_time_zone
  from private.salon_booking_settings as settings where settings.singleton;
  v_today := (pg_catalog.statement_timestamp() at time zone v_time_zone)::date;
  -- Compare salon wall times to local midnights, not a fixed 24-hour instant
  -- range. This also includes BOTH occurrences of a repeated midnight (e.g.
  -- America/Havana); converting an ambiguous midnight to one instant would
  -- silently exclude the earlier occurrence on a DST fallback day.
  v_today_start := v_today::timestamp;
  v_tomorrow_start := (v_today + 1)::timestamp;

  return query
  select booking.id, booking.customer_name, booking.phone, booking.service_id,
         service.name, booking.slot_time, booking.end_time, booking.status
  from public.bookings as booking
  join public.services as service on service.id = booking.service_id
  where (p_view = 'today'
           and (booking.slot_time at time zone v_time_zone) >= v_today_start
           and (booking.slot_time at time zone v_time_zone) < v_tomorrow_start)
     or (p_view = 'upcoming'
           and (booking.slot_time at time zone v_time_zone) >= v_tomorrow_start)
  order by booking.slot_time, booking.id
  limit p_limit offset p_offset;
end;
$$;
revoke all on function public.list_admin_bookings(text, integer, integer) from public, anon, authenticated;
grant execute on function public.list_admin_bookings(text, integer, integer) to authenticated;

create function public.admin_set_booking_status(
  p_booking_id uuid,
  p_status public.booking_status
)
returns table (
  id uuid,
  customer_name text,
  phone text,
  service_id uuid,
  slot_time timestamptz,
  end_time timestamptz,
  status public.booking_status
)
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_booking public.bookings%rowtype;
begin
  if not public.is_admin() then
    raise exception using errcode = '42501', message = 'ADMIN_REQUIRED';
  end if;
  if p_booking_id is null then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_INPUT';
  end if;
  if p_status is null or p_status not in ('confirmed', 'cancelled') then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_STATUS';
  end if;

  -- Serialize changes to this row so a concurrent cancellation cannot reopen it.
  select booking.* into v_booking
  from public.bookings as booking where booking.id = p_booking_id for update;
  if not found then
    raise exception using errcode = '22023', message = 'BOOKING_NOT_FOUND';
  end if;

  if v_booking.status is distinct from p_status then
    if v_booking.status not in ('pending', 'confirmed') then
      raise exception using errcode = '22023', message = 'BOOKING_STATUS_FINAL';
    end if;
    update public.bookings as booking set status = p_status
    where booking.id = v_booking.id returning booking.* into v_booking;
  end if;
  -- Exact confirmed/cancelled retries return the unchanged receipt.
  return query select v_booking.id, v_booking.customer_name, v_booking.phone,
    v_booking.service_id, v_booking.slot_time, v_booking.end_time, v_booking.status;
end;
$$;
revoke all on function public.admin_set_booking_status(uuid, public.booking_status) from public, anon, authenticated;
grant execute on function public.admin_set_booking_status(uuid, public.booking_status) to authenticated;

-- Source: supabase/migrations/20261005030000_allow_public_booking_inserts.sql
-- Preserve admin-only SELECT and existing RPCs; expose only the columns a
-- customer needs to submit an appointment request. IDs/status/end times are
-- database-owned. No anonymous booking SELECT or client UPDATE/DELETE grants.
revoke insert on table public.bookings from public, anon, authenticated;
revoke insert (id, customer_name, phone, service_id, slot_time, end_time, status)
  on table public.bookings from public, anon, authenticated;
grant insert (customer_name, phone, service_id, slot_time)
  on table public.bookings to anon, authenticated;

create policy "Public can submit bookings"
  on public.bookings
  for insert
  to anon, authenticated
  with check (status = 'pending'::public.booking_status);

-- Direct inserts must not bypass the RPC's schedule/contact checks. Definer
-- access is needed to read private salon settings without granting their use
-- to customers. Invocation remains trigger-only, with a fixed search path.
create function private.validate_public_booking_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_role text := coalesce(nullif(pg_catalog.current_setting('role', true), 'none'), session_user::text);
  v_time_zone text;
  v_today date;
  v_local_start timestamp;
  v_duration integer;
  v_now timestamptz;
begin
  -- Owner/service-role maintenance remains possible (e.g. importing historic
  -- bookings). SECURITY DEFINER RPCs keep the original SET ROLE value, so their
  -- API-origin inserts are checked here as well. No user-supplied metadata or
  -- request claim is used to decide whether validation is required.
  if v_role not in ('anon', 'authenticated') then
    return new;
  end if;

  new.customer_name := pg_catalog.btrim(new.customer_name);
  new.phone := pg_catalog.btrim(new.phone);
  if new.service_id is null or new.slot_time is null
     or not pg_catalog.isfinite(new.slot_time)
     or new.customer_name is null
     or pg_catalog.char_length(new.customer_name) not between 2 and 100
     or new.customer_name ~ '[[:cntrl:]]'
     or new.phone is null or pg_catalog.char_length(new.phone) > 32
     or new.phone !~ '^[0-9+(). -]+$'
     or pg_catalog.char_length(pg_catalog.regexp_replace(new.phone, '[^0-9]', '', 'g')) not between 7 and 15
     or new.status not in ('pending', 'confirmed') then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_INPUT';
  end if;

  select settings.time_zone into strict v_time_zone
  from private.salon_booking_settings as settings where settings.singleton for share;
  select service.duration into v_duration
  from public.services as service where service.id = new.service_id for share;
  if not found then
    raise exception using errcode = '22023', message = 'INVALID_SERVICE';
  end if;

  -- BEFORE triggers run in name order. The duration trigger already ran; derive
  -- again while holding the service lock to prevent a concurrent duration edit
  -- from shortening the interval the customer actually reserves.
  new.end_time := new.slot_time + pg_catalog.make_interval(mins => v_duration);
  v_now := pg_catalog.clock_timestamp();
  v_today := (v_now at time zone v_time_zone)::date;
  v_local_start := new.slot_time at time zone v_time_zone;
  if new.slot_time <= v_now then
    raise exception using errcode = '23P01', message = 'SLOT_UNAVAILABLE';
  end if;
  if v_local_start::date < v_today or v_local_start::date > v_today + 90
     or v_local_start::time < time '10:00' or v_local_start::time > time '19:30'
     or extract(minute from v_local_start) not in (0, 30)
     or extract(second from v_local_start) <> 0
     or (v_local_start at time zone v_time_zone) <> new.slot_time
     or new.end_time > (v_local_start::date + time '20:00') at time zone v_time_zone then
    raise exception using errcode = '22023', message = 'INVALID_BOOKING_INPUT';
  end if;

  -- Existing bookings_no_overlap is the race-safe enforcement layer for both
  -- direct inserts and RPC reservations; don't expose private rows to check it.
  return new;
end;
$$;
revoke all on function private.validate_public_booking_insert() from public, anon, authenticated;

create trigger bookings_validate_public_insert
before insert on public.bookings
for each row execute function private.validate_public_booking_insert();

comment on policy "Public can submit bookings" on public.bookings is
  'Guests and ordinary authenticated users can submit pending requests using customer fields only. Customer records remain admin-readable only.';

-- Source: supabase/migrations/20261005040000_validate_raw_service_values.sql
-- numeric(10,2) rounds before CHECK constraints see the input: 1.239 becomes
-- 1.24 and -0.001 becomes 0.00. Remove the typemod, not the monetary limits.
-- Existing prices retain their exact values; no service prices are rewritten.
alter table public.services alter column price type numeric using price::numeric;
alter table public.services
  drop constraint services_price_nonnegative,
  add constraint services_price_nonnegative
    check (price >= 0 and price not in ('NaN'::numeric, 'Infinity'::numeric, '-Infinity'::numeric)),
  add constraint services_price_two_decimals
    check (price = pg_catalog.trunc(price, 2));
-- services_price_admin_bounds still enforces the inclusive 99999999.99 maximum.
-- All CHECK constraints are validated, including against existing rows. Extra
-- trailing zeroes (e.g. 1.2300) represent a valid two-decimal monetary value.
comment on column public.services.price is
  'Finite nonnegative amount in the salon currency, not cents; at most two decimal places in value, maximum 99999999.99. Raw fractional cents are rejected, not rounded.';

-- This helper uses only NEW and schema-qualified builtins. It neither reads
-- private data nor elevates the writer's privileges; existing RLS/grants stay.
create function private.normalize_service_name()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.name := pg_catalog.btrim(new.name);
  return new;
end;
$$;
revoke all on function private.normalize_service_name() from public, anon, authenticated;

create trigger services_normalize_name
before insert or update on public.services
for each row execute function private.normalize_service_name();

-- Deliberately normalize existing outer space padding, including padding that
-- the old trimmed-length check allowed to exceed 120 stored characters. Keep
-- internal spaces, IDs, durations, prices and booking snapshots unchanged.
update public.services set name = pg_catalog.btrim(name)
where name is distinct from pg_catalog.btrim(name);

alter table public.services
  drop constraint services_name_admin_bounds,
  add constraint services_name_admin_bounds
    check (pg_catalog.char_length(name) between 1 and 120
      and name = pg_catalog.btrim(name)
      and name !~ '[[:cntrl:]]');
-- btrim removes outer spaces, not controls: tabs/newlines still fail the CHECK.
-- Bound the actual stored name, not merely a trimmed projection of it.
comment on column public.services.name is
  'Outer spaces are trimmed on insert/update. Stored names contain 1-120 characters and no control characters; internal spaces are preserved.';

commit;
